// Recebe a saida de "Buscar Grupos" e emite 1 item por grupo.
// A Evolution devolve { success, data: [ ...grupos... ] }; tratamos varios formatos.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const groups =
    (Array.isArray(j) && j) ||
    (Array.isArray(j.data) && j.data) ||
    (Array.isArray(j.groups) && j.groups) ||
    (j.data && Array.isArray(j.data.groups) && j.data.groups) ||
    [j];
  for (const g of groups) {
    const jid = g.id || g.remoteJid || g.jid;
    if (!jid || !String(jid).endsWith("@g.us")) continue;
    out.push({
      json: {
        group_jid: jid,
        name: g.subject || g.subjectOwner || g.name || null,
        instance: g.instanceId || "CONTAC.IA",
      },
    });
  }
}
return out;

// Achata as mensagens do(s) grupo(s) e mapeia p/ linhas de whatsapp_group_messages.
// LOOKBACK_HORAS = 0 -> pega TODO o historico (backfill, valor atual).
// No dia a dia (schedule 18h) troque para 24 (so as mensagens do dia).
const LOOKBACK_HORAS = 0;
const cutoffMs = LOOKBACK_HORAS > 0 ? Date.now() - LOOKBACK_HORAS * 3600 * 1000 : 0;

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  // Evolution embrulha em { success, data: ... }. As mensagens ficam em
  // data.messages.records (v2), ou data pode ser o proprio array.
  const d = j.data ?? j;
  const records =
    (d.messages && Array.isArray(d.messages.records) && d.messages.records) ||
    (Array.isArray(d.messages) && d.messages) ||
    (Array.isArray(d) && d) ||
    (Array.isArray(j) && j) ||
    [];

  for (const r of records) {
    const key = r.key || {};
    if (!key.id) continue;

    const groupJid = key.remoteJid || "";
    if (!groupJid.endsWith("@g.us")) continue; // so grupos

    let ts = r.messageTimestamp ?? null;
    const tsMs =
      typeof ts === "number"
        ? (ts < 1e12 ? ts * 1000 : ts)
        : ts
        ? new Date(ts).getTime()
        : Date.now();
    if (tsMs < cutoffMs) continue;

    // Remetente: nestes grupos NAO vem key.participant; quem enviou esta no pushName
    // (ex.: id @lid "36426406207491"). Usa participant se existir, senao o pushName.
    const sender = (key.participant && String(key.participant).split("@")[0]) || r.pushName || null;

    out.push({
      json: {
        clinic_id: null, // mapeado depois via whatsapp_groups (grupo -> clinica)
        instance: r.instanceId || "CONTAC.IA",
        group_jid: groupJid,
        message_id: key.id,
        from_me: key.fromMe === true,
        participant: sender,
        push_name: r.pushName || null,
        message_type: r.messageType || null,
        event_ts: new Date(tsMs).toISOString(),
      },
    });
  }
}
return out;
